#include "../v7/search.h"
#include <climits>
#include <ctime>
using namespace v2;
int main(int argc,char**argv){try{if(argc!=5)throw std::runtime_error("DEPTH SEED RESULT PROGRESS");init();Learner m;m.load("training/v7/base.ntd");Search s(m);s.maxNodes=INT_MAX;int depth=std::stoi(argv[1]);uint32_t seed=std::stoul(argv[2]);RNG rng{seed};Game g;g.reset(rng);Counts c=opening(g);std::ofstream out(argv[3]),progress(argv[4]);double cpu=0,maximum=0;uint64_t nodes=0;std::vector<double>times;while(!g.over&&high(g.b)<12&&g.turns<6000){auto begin=std::clock();auto a=s.choose(g.b,g.next,c,depth);double elapsed=double(std::clock()-begin)/CLOCKS_PER_SEC;if(s.completed!=depth)throw std::runtime_error("incomplete depth");cpu+=elapsed;maximum=std::max(maximum,elapsed);times.push_back(elapsed);nodes+=s.nodes;auto p=move(g.b,a.direction);if(!p.size)throw std::runtime_error("illegal action");g.advance(p,rng);c=observe(c,g.next);if(g.turns%25==0)progress<<"{\"moves\":"<<g.turns<<",\"rank\":"<<high(g.b)<<",\"searchCPU\":"<<cpu<<"}"<<std::endl;}if(!g.over&&high(g.b)<12)throw std::runtime_error("truncated game");std::sort(times.begin(),times.end());out<<std::setprecision(17)<<"{\"seed\":"<<seed<<",\"depth\":"<<depth<<",\"success\":"<<(high(g.b)>=12?"true":"false")<<",\"moves\":"<<g.turns<<",\"rank\":"<<high(g.b)<<",\"searchCPU\":"<<cpu<<",\"maxMoveCPU\":"<<maximum<<",\"medianMoveCPU\":"<<times[times.size()/2]<<",\"p95MoveCPU\":"<<times[std::min(times.size()-1,size_t(times.size()*.95))]<<",\"nodes\":"<<nodes<<"}"<<std::endl;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
